## Getting started

Create a `tsconfig.json` at the project root and rename your first file to `.ts` or `.tsx`. The first `pnpm dev` run auto-populates `tsconfig.json` with the Next.js-recommended settings:

```json
{
  "compilerOptions": {
    "target": "ES2017",
    "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true,
    "skipLibCheck": true,
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "preserve",
    "incremental": true,
    "plugins": [{ "name": "next" }],
    "paths": { "@/*": ["./src/*"] }
  },
  "include": ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts"],
  "exclude": ["node_modules"]
}
```

Don't edit the generated `next-env.d.ts` — Next.js regenerates it on each build.

## Framework types

### Page and layout props

```tsx
// app/blog/[slug]/page.tsx
import type { Metadata } from "next";

type Props = {
  params: Promise<{ slug: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
};

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  return { title: `Post: ${slug}` };
}

export default async function Page({ params, searchParams }: Props) {
  const { slug } = await params;
  return <article>{slug}</article>;
}
```

### Route Handlers

```ts
// app/api/users/route.ts
import { NextRequest, NextResponse } from "next/server";

export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const query = searchParams.get("q");
  // …
  return NextResponse.json({ data: [] });
}
```

### Middleware

```ts
// middleware.ts
import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";

export function middleware(request: NextRequest) {
  const token = request.cookies.get("token");
  if (!token) {
    return NextResponse.redirect(new URL("/login", request.url));
  }
  return NextResponse.next();
}
```

### Metadata

```ts
// app/layout.tsx
import type { Metadata } from "next";

export const metadata: Metadata = {
  title: { template: "%s | My App", default: "My App" },
  description: "My application",
  openGraph: {
    images: [{ url: "/og.png", width: 1200, height: 630 }],
  },
};
```

## Strict mode

Enable `strict: true` in `tsconfig.json` (it's the default in `create-next-app`). This catches:

- Null / undefined without narrowing
- Implicit `any` from untyped props
- `noUncheckedIndexedAccess` — array index returns `T | undefined`
- `noImplicitOverride` — explicit `override` keyword on class method overrides

## Path aliases

```ts
// tsconfig.json paths
"paths": { "@/*": ["./src/*"] }

// In code
import { db } from "@/lib/db";
import { Button } from "@/components/ui/button";
```

Next.js reads `paths` from `tsconfig.json` and configures both the bundler and the TypeScript language server to resolve them.

## Type checking in CI

```json
// package.json
"scripts": {
  "type-check": "tsc --noEmit"
}
```

Run `pnpm type-check` in CI before `pnpm build`. `next build` also type-checks, but a separate `tsc` step gives faster feedback and a clearer error output.

## error.tsx — the error boundary

An `error.tsx` file acts as a React error boundary for its route segment and all children. It must be a Client Component:

```tsx
// app/dashboard/error.tsx
"use client";

import { useEffect } from "react";

export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    // Log to your error reporting service
    console.error(error);
  }, [error]);

  return (
    <div className="flex flex-col items-center gap-4 p-8">
      <h2>Something went wrong</h2>
      <p className="text-sm text-gray-500">{error.message}</p>
      <button onClick={reset}>Try again</button>
    </div>
  );
}
```

`reset()` re-renders the segment from scratch — useful when the error was transient (network flap, temporary API outage).

## not-found.tsx — expected 404s

For routes where a resource might not exist, call `notFound()` and handle it with `not-found.tsx`:

```tsx
// app/products/[id]/page.tsx
import { notFound } from "next/navigation";

export default async function ProductPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const product = await getProduct(id);

  if (!product) notFound(); // throws → caught by not-found.tsx

  return <ProductView product={product} />;
}
```

```tsx
// app/products/[id]/not-found.tsx
export default function NotFound() {
  return (
    <div>
      <h2>Product not found</h2>
      <p>This product doesn't exist or has been removed.</p>
    </div>
  );
}
```

Next.js sets the correct 404 status code automatically.

## Nesting and scope

Error and not-found files are scoped to their segment. A crash in `/dashboard/settings` triggers `app/dashboard/settings/error.tsx` first, then `app/dashboard/error.tsx`, then the global `app/error.tsx` — whichever is nearest:

```
app/
├── error.tsx              ← global fallback
├── not-found.tsx          ← global 404
├── dashboard/
│   ├── error.tsx          ← catches dashboard subtree errors
│   ├── page.tsx
│   └── settings/
│       ├── error.tsx      ← catches settings errors first
│       └── page.tsx
```

Scope the error boundary as tightly as possible — a settings crash shouldn't hide the dashboard nav.

## global-error.tsx — root layout errors

For errors that occur in the root `app/layout.tsx` itself, `app/error.tsx` can't catch them (error boundaries don't catch errors in the same component they're rendered in). Use `app/global-error.tsx` instead:

```tsx
// app/global-error.tsx
"use client";

export default function GlobalError({
  error,
  reset,
}: {
  error: Error;
  reset: () => void;
}) {
  return (
    <html>
      <body>
        <h1>Something went wrong</h1>
        <button onClick={reset}>Reload</button>
      </body>
    </html>
  );
}
```

Note: must include `<html>` and `<body>` — it replaces the root layout.

## Pages Router equivalents

| App Router | Pages Router |
| --- | --- |
| `error.tsx` | `_error.tsx` |
| `not-found.tsx` | `404.tsx` |
| `global-error.tsx` | `500.tsx` |
| `notFound()` helper | `res.statusCode = 404; return { notFound: true }` in getServerSideProps |

## Static metadata export

The simplest form — export a typed `Metadata` object from any `layout.tsx` or `page.tsx`:

```tsx
// app/layout.tsx
import type { Metadata } from "next";

export const metadata: Metadata = {
  title: {
    template: "%s | Acme Corp",
    default: "Acme Corp",
  },
  description: "Enterprise software built for scale",
  openGraph: {
    siteName: "Acme Corp",
    type: "website",
    images: [
      {
        url: "/og-default.png",
        width: 1200,
        height: 630,
        alt: "Acme Corp",
      },
    ],
  },
  twitter: {
    card: "summary_large_image",
    creator: "@acmecorp",
  },
  robots: {
    index: true,
    follow: true,
  },
};
```

All pages inherit this and override with their own.

## Dynamic metadata with generateMetadata

When the metadata depends on data (e.g., a blog post title), export an async function:

```tsx
// app/blog/[slug]/page.tsx
import type { Metadata } from "next";
import { getPost } from "@/lib/posts";
import { notFound } from "next/navigation";

type Props = {
  params: Promise<{ slug: string }>;
};

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  const post = await getPost(slug);

  if (!post) return { title: "Not found" };

  return {
    title: post.title,
    description: post.excerpt,
    openGraph: {
      title: post.title,
      description: post.excerpt,
      images: [{ url: post.ogImage }],
      type: "article",
      publishedTime: post.publishedAt,
    },
  };
}

export default async function BlogPost({ params }: Props) {
  const { slug } = await params;
  const post = await getPost(slug);
  if (!post) notFound();
  return <article>{post.body}</article>;
}
```

Next.js deduplicates the `getPost` fetch between `generateMetadata` and the page — it only runs once.

## Title templates

```tsx
// app/layout.tsx — root template
export const metadata: Metadata = {
  title: { template: "%s | Acme", default: "Acme" },
};

// app/blog/page.tsx — child page
export const metadata: Metadata = {
  title: "Blog",  // becomes "Blog | Acme"
};

// app/blog/[slug]/page.tsx — deeper child
export const metadata: Metadata = {
  title: "How I optimised LCP",  // becomes "How I optimised LCP | Acme"
};
```

The `%s` is replaced with the child's `title`. Use `absolute` to bypass the template:

```tsx
export const metadata: Metadata = {
  title: { absolute: "Special Launch Page" },
};
```

## Favicon and icons

```tsx
export const metadata: Metadata = {
  icons: {
    icon: "/favicon.ico",
    shortcut: "/shortcut-icon.png",
    apple: "/apple-touch-icon.png",
  },
};
```

Or use the file convention — drop `icon.png`, `apple-icon.png`, or `opengraph-image.png` into a route folder and Next.js picks them up automatically.

## Generated OG images

```tsx
// app/blog/[slug]/opengraph-image.tsx
import { ImageResponse } from "next/og";

export default async function OGImage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const post = await getPost(slug);

  return new ImageResponse(
    <div style={{ display: "flex", fontSize: 48 }}>{post.title}</div>,
    { width: 1200, height: 630 },
  );
}
```

Next.js generates a `.png` from the JSX at request time. No external image generation service needed.

## vs. the old Head component

| Approach | When |
| --- | --- |
| `export const metadata` | Static — resolved at build time |
| `export async function generateMetadata` | Dynamic — needs data from APIs or DB |
| `<Head>` (Pages Router) | Per-page imperative tag injection — not available in App Router |

## Global CSS

Import once in the root layout. Applies to every page:

```tsx
// app/layout.tsx
import "./globals.css";

export default function RootLayout({ children }) {
  return (
    <html>
      <body>{children}</body>
    </html>
  );
}
```

In `globals.css` you reset styles, define CSS custom properties, and set base font styles. Next.js compiles and deduplicates the CSS for production.

## CSS Modules

Any file ending in `.module.css` is treated as a CSS Module — class names are locally scoped by default:

```css
/* card.module.css */
.root {
  background: white;
  border-radius: 8px;
  padding: 1rem;
}

.title {
  font-size: 1.25rem;
  font-weight: 600;
}
```

```tsx
// card.tsx
import styles from "./card.module.css";

export function Card({ title }: { title: string }) {
  return (
    <div className={styles.root}>
      <h2 className={styles.title}>{title}</h2>
    </div>
  );
}
```

The compiled class names include a unique hash — `.card_title__xQk92` — so there are no collisions across components.

## Sass

Install `sass` and rename your files to `.scss` or `.sass`. No config needed:

```bash
pnpm add -D sass
```

```scss
// variables.scss
$primary: #0070f3;

// button.module.scss
@use "./variables" as *;

.button {
  background: $primary;
  &:hover { opacity: 0.9; }
}
```

## Tailwind CSS

The most popular choice for new Next.js projects. Install via `create-next-app --tailwind` or add manually:

```bash
pnpm add tailwindcss @tailwindcss/postcss postcss
```

```tsx
export function Button({ children }: { children: React.ReactNode }) {
  return (
    <button className="rounded-lg bg-blue-600 px-4 py-2 text-white hover:bg-blue-700">
      {children}
    </button>
  );
}
```

Works perfectly in Server Components — Tailwind classes are resolved at build time, no runtime JS needed.

## CSS-in-JS with Server Components

Libraries like styled-components and Emotion inject styles at runtime — they need a registry to collect styles during SSR and flush them to the initial HTML:

```tsx
// app/registry.tsx
"use client";
import { useState } from "react";
import { useServerInsertedHTML } from "next/navigation";
import { ServerStyleSheet, StyleSheetManager } from "styled-components";

export function StyledComponentsRegistry({ children }) {
  const [styledComponentsStyleSheet] = useState(() => new ServerStyleSheet());

  useServerInsertedHTML(() => (
    <>{styledComponentsStyleSheet.getStyleElement()}</>
  ));

  if (typeof window !== "undefined") return <>{children}</>;

  return (
    <StyleSheetManager sheet={styledComponentsStyleSheet.instance}>
      {children}
    </StyleSheetManager>
  );
}
```

This complexity is why most teams starting fresh with App Router reach for Tailwind instead.

## Choosing an approach

| Approach | Runtime cost | Server Component compatible | Good for |
| --- | --- | --- | --- |
| CSS Modules | Zero | Yes | Component-scoped styles |
| Tailwind | Zero | Yes | Utility-first, fast iteration |
| Sass | Zero | Yes | Teams comfortable with SCSS |
| styled-components | Yes (registry) | With registry | Existing codebases |
| Emotion | Yes (registry) | With registry | Existing codebases |

## The basic pattern

```tsx
import dynamic from "next/dynamic";

const HeavyChart = dynamic(() => import("./heavy-chart"), {
  loading: () => <div className="h-64 animate-pulse bg-gray-200" />,
});

export default function Dashboard() {
  return (
    <section>
      <h1>Analytics</h1>
      <HeavyChart /> {/* JS for HeavyChart loads only when rendered */}
    </section>
  );
}
```

The bundle for `/dashboard` no longer includes HeavyChart's code. It downloads only when that component is rendered.

## ssr: false — browser-only components

Some components use APIs that only exist in the browser (`window`, `document`, `localStorage`, WebGL, canvas). Rendering them on the server throws:

```tsx
const Map = dynamic(() => import("./map"), {
  ssr: false,           // skip server render
  loading: () => <MapSkeleton />,
});

export default function Page() {
  return <Map center={[51.5, -0.09]} zoom={13} />;
}
```

With `ssr: false`, Next.js skips the component on the server and renders it in the browser after hydration.

## Named exports

```tsx
const { DataTable } = dynamic(
  () => import("@/components/data-table").then((mod) => mod),
);

// Or directly:
const DataTable = dynamic(
  async () => (await import("@/components/data-table")).DataTable,
);
```

## Preloading

For components likely to be needed soon (hover, focus), you can preload them before the user triggers the render:

```tsx
const Modal = dynamic(() => import("./modal"));

export function TriggerButton() {
  // Preload on hover — so the modal feels instant when clicked
  return (
    <button
      onMouseEnter={() => Modal.preload()}
      onClick={() => setOpen(true)}
    >
      Open modal
    </button>
  );
}
```

## App Router — React.lazy + Suspense directly

In App Router you can skip `next/dynamic` and use standard React:

```tsx
"use client";
import { lazy, Suspense } from "react";

const HeavyChart = lazy(() => import("./heavy-chart"));

export function Dashboard() {
  return (
    <Suspense fallback={<ChartSkeleton />}>
      <HeavyChart />
    </Suspense>
  );
}
```

Prefer `next/dynamic` when you need `ssr: false` or the preload API; use `React.lazy` otherwise — it's the standard primitive.

## When to reach for it

- Rich editors (CodeMirror, Quill, TipTap) — large, browser-only
- Charting libraries (Recharts, D3 heavy setup, Chart.js)
- Map components (Leaflet, Mapbox)
- Modals, drawers, and tooltips that aren't rendered on first paint
- Anything where the build output shows an unexpectedly large First Load JS

## When not to bother

- Small utility components — the overhead of splitting may cost more than it saves
- Components that always render above the fold — they need to be there immediately
- Server Components — they already don't ship JS to the browser; dynamic imports are a client-side concern

## Automatic route-level splitting

Every page in `app/` (or `pages/`) becomes its own JS chunk. A user on `/about` never downloads the JS for `/checkout`:

```
pnpm build output:

Route (app)                              Size     First Load JS
┌ ○ /                                    1.1 kB        87 kB
├ ○ /about                               0.8 kB        84 kB
├ ○ /blog                                2.4 kB        88 kB
└ ƒ /checkout                            4.2 kB        92 kB

+ First Load JS shared by all            83.2 kB
  ├ chunks/framework-<hash>.js           45 kB
  ├ chunks/main-<hash>.js                28 kB
  └ chunks/pages/_app-<hash>.js          10 kB
```

The `First Load JS shared by all` is the baseline everyone downloads — the React runtime, the Next.js router, and widely-used utilities. The `Size` column is what's added per route.

## Server Components — the biggest reduction

Server Components don't ship any JS to the browser — their code runs on the server and the result (HTML or RSC payload) is sent to the client:

```tsx
// Server Component — zero browser JS
export default async function ProductList() {
  const products = await db.product.findMany();
  return (
    <ul>
      {products.map((p) => <li key={p.id}>{p.name}</li>)}
    </ul>
  );
}
```

Moving a 50kB library (like a Markdown parser) into a Server Component removes it from the bundle entirely.

## next/dynamic — within-route splitting

For components on a route that aren't needed immediately:

```tsx
import dynamic from "next/dynamic";

// Not loaded until the component renders
const RichEditor = dynamic(() => import("@/components/rich-editor"), {
  loading: () => <EditorSkeleton />,
});

export default function Page() {
  const [editing, setEditing] = useState(false);
  return (
    <div>
      <button onClick={() => setEditing(true)}>Edit</button>
      {editing && <RichEditor />}
    </div>
  );
}
```

The `RichEditor` bundle only downloads when the user clicks Edit.

## What causes a large bundle

The most common culprits:

```tsx
// ❌ Heavy library imported in a Client Component
"use client";
import { Chart } from "chart.js"; // 200kB in your bundle

// ✅ Lazy-load it
const Chart = dynamic(() => import("./chart-wrapper"));

// ❌ Heavy library used only for a single value — import the function
import { format } from "date-fns"; // tree-shakes poorly

// ✅ Import from the specific subpath
import { format } from "date-fns/format";
```

## Analysing the bundle

```bash
# Install the analyser
pnpm add -D @next/bundle-analyzer

# next.config.ts
import bundleAnalyzer from "@next/bundle-analyzer";
const withBundleAnalyzer = bundleAnalyzer({
  enabled: process.env.ANALYZE === "true",
});
export default withBundleAnalyzer({});

# Run
ANALYZE=true pnpm build
```

The visualisation shows each module's contribution to each chunk — easy to spot the library that's taking 30% of the bundle.
